def calculate_fault_scores(
    frequencies,
    amplitude,
    rpm
):
    shaft_freq = rpm / 60

    bpfi = 5.4152 * shaft_freq
    bpfo = 3.5848 * shaft_freq
    bsf  = 4.7135 * shaft_freq

    bpfi_score, _ = harmonic_score(
        frequencies, amplitude, bpfi
    )

    bpfo_score, _ = harmonic_score(
        frequencies, amplitude, bpfo
    )

    bsf_score, _ = harmonic_score(
        frequencies, amplitude, bsf
    )

    return {
        "BPFI_score": bpfi_score,
        "BPFO_score": bpfo_score,
        "BSF_score": bsf_score
    }

